/// Evaluate an integer arithmetic expression and return its value, or None
/// if the expression is invalid.
/// Tokens are non-negative decimal integer literals (one or more ASCII digits),
/// the operators + - * / % ^ and the parentheses ( ). Space characters (' ')
/// may appear between tokens and are ignored; any other character, tabs
/// included, makes the expression invalid.
/// Precedence, from lowest to highest:
///   1. binary + and -, left-associative;
///   2. binary *, / and %, left-associative;
///   3. prefix unary minus, which may repeat ("--3" is 3);
///   4. ^ (power), right-associative ("2^3^2" is 2^9); it binds tighter than a
///      unary minus on its left ("-2^2" is -4), and its right operand may start
///      with unary minus ("2^-1" parses, then fails as a negative exponent);
///   5. integer literals and parenthesized expressions.
/// / truncates toward zero and % takes the sign of the dividend, as in C
/// ("-7 / 2" is -3 and "-7 % 2" is -1). 0^0 is 1.
/// Return None for an empty or all-space expression, any syntax error (a missing
/// operand, two adjacent numbers such as "1 2", empty or unbalanced
/// parentheses), division or remainder by zero, and a negative exponent.
/// Every value in the tests fits in a signed 64-bit integer.
/// >>> eval_arith(String::from("2 + 3 * (4 - 1)"))
/// Some(11)
/// >>> eval_arith(String::from("2 ^ 3 ^ 2"))
/// Some(512)
fn eval_arith(expr: String) -> Option<i64> {
    let cs: Vec<char> = expr.chars().collect();
    let mut toks: Vec<Tok> = Vec::new();
    let mut i = 0;
    while i < cs.len() {
        let c = cs[i];
        if c == ' ' {
            i += 1;
        } else if c.is_ascii_digit() {
            let j = (i..cs.len()).find(|&k| !cs[k].is_ascii_digit()).unwrap_or(cs.len());
            toks.push(Tok::Num(cs[i..j].iter().collect::<String>().parse().ok()?));
            i = j;
        } else if "+-*/%^()".contains(c) {
            toks.push(Tok::Sym(c));
            i += 1;
        } else {
            return None;
        }
    }
    let mut p = Parser { toks, pos: 0 };
    let v = p.sum()?;
    if p.pos == p.toks.len() { Some(v) } else { None }
}

enum Tok {
    Num(i64),
    Sym(char),
}

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
}

impl Parser {
    fn sym(&self) -> char {
        match self.toks.get(self.pos) {
            Some(Tok::Sym(c)) => *c,
            _ => '\0',
        }
    }

    fn sum(&mut self) -> Option<i64> {
        let mut v = self.product()?;
        while self.sym() == '+' || self.sym() == '-' {
            let op = self.sym();
            self.pos += 1;
            let r = self.product()?;
            v = if op == '+' { v + r } else { v - r };
        }
        Some(v)
    }

    fn product(&mut self) -> Option<i64> {
        let mut v = self.unary()?;
        while matches!(self.sym(), '*' | '/' | '%') {
            let op = self.sym();
            self.pos += 1;
            let r = self.unary()?;
            if op != '*' && r == 0 {
                return None;
            }
            v = match op { '*' => v * r, '/' => v / r, _ => v % r };
        }
        Some(v)
    }

    fn unary(&mut self) -> Option<i64> {
        if self.sym() == '-' {
            self.pos += 1;
            return Some(-self.unary()?);
        }
        self.power()
    }

    fn power(&mut self) -> Option<i64> {
        let base = self.atom()?;
        if self.sym() != '^' {
            return Some(base);
        }
        self.pos += 1;
        let e = self.unary()?;
        if e < 0 { None } else { Some(base.pow(e as u32)) }
    }

    fn atom(&mut self) -> Option<i64> {
        match self.toks.get(self.pos) {
            Some(Tok::Num(v)) => {
                let v = *v;
                self.pos += 1;
                Some(v)
            }
            Some(Tok::Sym('(')) => {
                self.pos += 1;
                let v = self.sum()?;
                if self.sym() != ')' {
                    return None;
                }
                self.pos += 1;
                Some(v)
            }
            _ => None,
        }
    }
}
